import{_ as r,o as t,c as s,a3 as l,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const g="/bilder/vorbereitung/teilleistungsnoten-eingeben.png",o="/bilder/vorbereitung/gruppenprozesse-noteneingabe-vorbereitete-teilleistungen-01.png",a="/bilder/vorbereitung/gruppenprozesse-noteneingabe-vorbereitete-teilleistungen-02.png",u="/bilder/vorbereitung/gruppenprozesse-noteneingabe-vorbereitete-teilleistungen-03.png",T=JSON.parse('{"title":"Noten für vorbereitete Teilleistungen eingeben","description":"","frontmatter":{"title":"Noten für vorbereitete Teilleistungen eingeben","source_pageid":321,"source_revision":5382},"headers":[],"relativePath":"zeugnisse/vorbereitung/noteneingabe-nur-vorbereitete-tl-gruppenprozesse-teilleistungen.md","filePath":"zeugnisse/vorbereitung/noteneingabe-nur-vorbereitete-tl-gruppenprozesse-teilleistungen.md"}'),p={name:"zeugnisse/vorbereitung/noteneingabe-nur-vorbereitete-tl-gruppenprozesse-teilleistungen.md"};function b(d,i,c,h,m,f){return t(),s("div",null,[...i[0]||(i[0]=[l('<h1 id="noten-fur-vorbereitete-teilleistungen-eingeben" tabindex="-1">Noten für vorbereitete Teilleistungen eingeben <a class="header-anchor" href="#noten-fur-vorbereitete-teilleistungen-eingeben" aria-label="Permalink to &quot;Noten für vorbereitete Teilleistungen eingeben&quot;">​</a></h1><p><a href="/bilder/vorbereitung/teilleistungsnoten-eingeben.png"><img src="'+g+'" alt="Teilleistungseingabe mit der Option zum Überschreiben vorhandener Datumsangaben" loading="lazy"></a></p><p><em>Teilleistungseingabe mit der Option zum Überschreiben vorhandener Datumsangaben — Oberfläche von SchILD-NRW 3.6.0.</em></p><p>Wählen Sie eine bereits zugewiesene Teilleistung und erfassen Sie Noten, Datum und Bemerkungen für die Schülergruppe. Übernehmen Sie die fertige Tabelle anschließend in die Datenbank.</p><p><a href="/bilder/vorbereitung/gruppenprozesse-noteneingabe-vorbereitete-teilleistungen-01.png"><img src="'+o+'" alt="Auswahl von Fach und Teilleistungsart der einzugebenden Teilleistungen über Gruppenprozesse ➜ Teilleistungen ➜ Noteneingabe (nur vorbereitete TL)." loading="lazy"></a></p><p><em>Auswahl von Fach und Teilleistungsart der einzugebenden Teilleistungen über Gruppenprozesse ➜ Teilleistungen ➜ <strong>Noteneingabe (nur vorbereitete TL)</strong>.</em></p><p>Durch den Gruppenprozess <strong>Noteneingabe (nur vorbereitete TL)</strong> können für die ausgewählte Schülergruppe Noten für vorhandene Teilleistungen eingegeben werden.</p><p>Um die in den vorherigen Gruppenprozessen vorbereiteten und angelegten Teilleistungen mit Leistungsdaten zu füllen, kann dieser Gruppenprozess verwendet werden.</p><p>Im sich öffnenden Fenster kann für die ausgewählte Schülermenge im Container eine bereits angelegte Teilleistung über die zwei Dropdown-Menüs ausgewählt werden.</p><p>Im Beispiel sind für die Lerngruppe nur im Fach Deutsch die angezeigten fünf Teilleistungsarten angelegt.</p><p><a href="/bilder/vorbereitung/gruppenprozesse-noteneingabe-vorbereitete-teilleistungen-02.png"><img src="'+a+'" alt="Schülertabelle für die Teilleistungseingabe." loading="lazy"></a></p><p><em>Schülertabelle für die Teilleistungseingabe.</em></p><p>Durch Klick auf <code>Aktualisieren</code> wird die Schüler-Tabelle geladen, die in der Folge gefüllt werden kann.</p><p>Über <strong>Datum übernehmen</strong> übertragen Sie das oben rechts eingestellte Datum. Mit <strong>Datum auch übernehmen, wenn schon vorhanden</strong> bestimmen Sie, ob bereits vorhandene Datumsangaben dabei überschrieben werden. Ein Datum ist bei der gruppenweisen Teilleistungseingabe nicht zwingend erforderlich.</p><p>Unter <strong>Note</strong> können nur zulässige Werte für Leistungsdaten eingegeben werden.</p><p>Über das Feld <strong>Bemerkung</strong> können freie Texte erfasst werden.</p><p>Die Noteneingabe wird abgeschlossen durch Klick auf die Schaltfäche <code>In Datenbank übernehmen</code>.</p><p><a href="/bilder/vorbereitung/gruppenprozesse-noteneingabe-vorbereitete-teilleistungen-03.png"><img src="'+u+'" alt="Ansicht eingetragener Teilleistungen im aktuellen Abschnitt des jeweiligen Schülers." loading="lazy"></a></p><p><em>Ansicht eingetragener Teilleistungen im aktuellen Abschnitt des jeweiligen Schülers.</em></p><p>Als Resultat erscheinen die eingetragenen Teilleistungen im aktuellen Abschnitt eines ausgewählten Schülers durch Klick auf das <strong>+</strong> beim entsprechenden <strong>Fach</strong> im Reiter <em>Schüler ➜ Aktueller Abschnitt</em> ➜ <strong>Leistungsdaten</strong>.</p>',20),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Die Teilleistungen können in SchILD-NRW selbst nur funktionsbezogen eingegeben werden, das bedeutet, der SchILD-Benutzer muss über entsprechende Berechtigungen verfügen. Dies ist in vielen Schulen jedoch häufig nur Lehrkräften in zum Beispiel Verwaltungs- oder Schulleitungsaufgaben vorbehalten."),e("p",null,[n("Die Notenerfassung mit GradeHub und WeNoM ist dem SVWS-Server zugeordnet. Einrichtung und Bedienung sind in der "),e("a",{href:"https://doku.svws-nrw.de/",target:"_blank",rel:"noreferrer"},"SVWS-Dokumentation"),n(" beschrieben; siehe auch "),e("a",{href:"/zeugnisse/noteneingabe.html"},"Noten mit GradeHub und WeNoM erfassen"),n(".")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Noteneingabe_(nur_vorbereitete_TL)_(Gruppenprozesse_Teilleistungen)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5382.")],-1)])])}const k=r(p,[["render",b]]);export{T as __pageData,k as default};
